lines_only = {
    **config,
    "topology_perturbation": {
        "type": "random",
        "k": 1,
        "n_topology_variants": 5,
        "elements": ["branch"],
    },
    "settings": {**config["settings"], "data_dir": "outputs/part2/lines_only"},
}
Path("outputs/part2/lines_only.yaml").write_text(yaml.safe_dump(lines_only))

import subprocess
